export function templeArt(level=0){return `<svg viewBox="0 0 340 180" class="temple" fill="none" aria-label="Temple level ${level}"><g stroke="currentColor" stroke-width="2"><path d="M40 150h260v10H40zm12-10h236v10H52" fill="#e9c77715"/>${level>=1?'<path d="M65 130h210v10H65zM65 70h210v10H65zM55 70l115-50 115 50z" fill="#e9c77718"/><path d="m77 63 93-33 93 33z"/><path d="M80 80v50m180-50v50" stroke-width="12"/>':'<path d="m75 130 25-13 30 9 30-13 35 9 30-6 40 14" stroke-dasharray="4 6" opacity=".5"/>'}${level>=2?'<path d="M112 80v50m32-50v50m52-50v50m32-50v50" stroke-width="10"/><circle cx="170" cy="53" r="10"/>':''}${level>=3?'<path d="m170 44-5 10h7l-4 10 10-14h-7l4-6" fill="currentColor"/><path d="M80 15v20m-10-10h20m170-10v20m-10-10h20" opacity=".5"/><circle cx="170" cy="88" r="64" opacity=".1" class="glowring"/>':''}</g></svg>`}
