function baseBossArt(type=0){
 if(type%4===0)return hydraArt(type);
 const wrap=(name,body)=>`<svg viewBox="0 0 300 240" fill="none" role="img" aria-label="Animated ${name} boss"><ellipse cx="150" cy="216" rx="98" ry="9" fill="#000" opacity=".2"/>${body}</svg>`;
 if(type%4===1)return wrap('Cerberus',`<g stroke="#a28caf" stroke-width="1.5"><path d="M65 200v-40q5-38 80-35 77-2 87 37v38l-27 11-25-22h-61l-25 22z" fill="#40364e"/><path d="m66 175-25-36 16 5-6-24 26 28m147 12 23-32-1 35-19 25" fill="#5d4a65"/>${[-1,0,1].map((n,i)=>`<g class="bosshead ${i===1?'two':i===2?'three':''}"><path d="m${150+n*61} ${60+Math.abs(n)*20} -22-25-7 38-12 18 7 35 32 19 31-20 8-34-12-18-6-39z" fill="${i===1?'#75617a':'#5a4865'}"/><path d="m${123+n*61} ${105+Math.abs(n)*20} 27 12 28-12-8 26-21 8-20-10z" fill="#251e30"/><path d="m${131+n*61} ${91+Math.abs(n)*20} 9 2m18-2 10-2" stroke="#edca8e" stroke-width="4" class="eye"/><path d="m${136+n*61} ${122+Math.abs(n)*20} 4 9 5-8m13 0 5 8 3-10" fill="#e2d7bc"/></g>`).join('')}<path d="M108 183h84" stroke="#bda381" stroke-width="8"/><circle cx="150" cy="182" r="9" fill="#d3bb81"/></g>`);
 if(type%4===2)return wrap('Leviathan',`<g class="float" stroke="#8cc7ac" stroke-width="1.5"><path d="M58 193q-25-56 45-64 78-11 92 29 18 49-39 49-62 0-44-30 11-19 40-8" stroke="#426e5f" stroke-width="33"/><path d="M57 188q-10-50 50-50 102-5 77 50-24 30-64-3" stroke="#83aa82" opacity=".5" stroke-width="3"/><g class="bosshead"><path d="M190 173q-11-58-37-78l-10-22 13-17-8-26 26 18 21-3 26 20-12 22-22 10q32 45 30 76" fill="#4e8972"/><path d="m156 69 26 9 26-5-15 18-29-6z" fill="#173e37"/><path d="m162 86 5 11 7-10m12 2 4 9 8-11" fill="#d6dfb5"/><path d="m171 61 9 2" stroke="#efce7e" stroke-width="4" class="eye"/><path d="m154 106-19 5 28 13-16 12 29 8-15 14 27 7" fill="#649a76"/></g><path d="m52 157-23-15 8 30-13 8 29 13" fill="#6e9f82"/></g><g class="particles" stroke="#8cc7ac" opacity=".5"><circle cx="243" cy="96" r="7"/><circle cx="67" cy="66" r="4"/><circle cx="238" cy="178" r="4"/></g>`);
 return wrap('Titan',`<g class="float" stroke="#b8a176" stroke-width="1.5"><path d="m115 163-16 44 29 5 24-39 20 38 31-6-17-46" fill="#62694f"/><path d="m107 84-33 22-19 61 23 13 28-48 6 39 74 1 9-43 27 50 23-13-23-64-33-19z" fill="#777957"/><path d="m113 96 37 18 37-18-14 57-45-1z" fill="#555f48"/><g class="bosshead"><path d="m124 40 25-11 26 13 5 32-17 23-27-2-17-24z" fill="#8c8c67"/><path d="m122 51-14-25 22 13m41 0 23-13-16 30" fill="#aaa17a"/><path d="m132 58 10 3m14 0 10-3" stroke="#efd48e" stroke-width="4" class="eye"/><path d="m140 80 19 0"/><path d="m146 37 3 12-7 8 8 14-3 11" stroke="#e9c777" opacity=".6"/></g><path d="m83 117-9 22 8 9-12 18m141-51 12 22-8 12 10 16m-78-49 9 15-8 12 10 13" stroke="#e9c777" opacity=".55"/><circle cx="151" cy="128" r="8" fill="#e9c777" class="glowring"/></g>`)
}

// Presentation is derived from existing progress; no new saved state is needed.
export function bossPhase({damage,max}){return damage>=max?'defeated':damage>=max/2?'awakened':'dormant'}
export function bossArt(type=0,awakened=false){
 const svg=baseBossArt(type);
 if(!awakened)return svg;
 const aura=`<g class="rage-aura" stroke="#efb477" fill="none"><circle cx="150" cy="120" r="100" opacity=".35"/><circle cx="150" cy="120" r="109" stroke-dasharray="3 15" opacity=".5"/>${Array.from({length:8},(_,i)=>`<path d="M150 9l-6 14 6-3 5 14" transform="rotate(${i*45} 150 120)" opacity=".65"/>`).join('')}</g>`;
 return svg.replace('fill="none"','class="boss-awakened" fill="none"').replace('<ellipse',aura+'<ellipse').replace('</svg>','<g class="rage-embers" fill="#ffd39b"><circle cx="65" cy="145" r="2"/><circle cx="240" cy="100" r="3"/><circle cx="100" cy="60" r="2"/><circle cx="210" cy="190" r="2"/></g></svg>');
}
export function realmName(stage=0){return ['The foothills','Gates of Sparta','The sacred grove','Temple of light','Temple of light','The celestial summit','The celestial summit'][stage]||'The foothills'}
export function realmArt(stage=0){
 const temple=stage>=3,cosmic=stage>=5;
 return `<svg class="realm-art" viewBox="0 0 600 360" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><circle class="realm-sun" cx="430" cy="92" r="${cosmic?42:32}" fill="currentColor" opacity=".12"/>${cosmic?'<ellipse class="realm-orbit" cx="430" cy="92" rx="73" ry="20" transform="rotate(-25 430 92)" stroke="currentColor" fill="none" opacity=".22"/>':''}<g class="realm-stars" fill="currentColor" opacity=".35">${Array.from({length:cosmic?20:7},(_,i)=>`<circle cx="${(i*79+37)%580}" cy="${(i*43+20)%170}" r="${i%3===0?2:1}"/>`).join('')}</g><path d="M0 240 95 120 175 224 277 103 389 235 498 141 600 240V360H0z" fill="currentColor" opacity=".055"/><path d="M0 282 133 204 253 267 384 175 510 254 600 210V360H0z" fill="currentColor" opacity=".08"/>${temple?'<g class="realm-temple" stroke="currentColor" fill="none" opacity=".2"><path d="M335 290h220M345 280h200M355 194h180l-90-44z"/><path d="M368 200v78m37-78v78m40-78v78m40-78v78m37-78v78" stroke-width="8"/><path d="M345 288h200" stroke-width="5"/></g>':stage>=1?`<g stroke="currentColor" opacity=".17"><path d="M370 290V185h18v105m116 0V185h18v105" stroke-width="6"/><path d="M359 181h40m94 0h40" stroke-width="5"/>${stage>=2?'<path d="M405 288q40-135 80 0" fill="none"/><path d="m419 225 14-12m39 12-14-12"/>':''}</g>`:''}<path d="M0 320q150-45 300-6t300-2v48H0z" fill="currentColor" opacity=".09"/><g class="realm-mist" stroke="currentColor" opacity=".12"><path d="M20 300h170m130 25h220M80 340h140"/></g></svg>`;
}
